Action.Str:
function pad(n) { return ('0' + n).slice(-2); }
var d = new Date();
var today = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
// Only this notification's own title, %evtprm2. Not %NTITLE, which is the
// last notification shown rather than the one that fired this profile, and
// not the body, where a failure alert could quote a digest title.
// A failure alert, or yesterday's digest arriving late, must not count.
var m = /^homelab digest (\d{4}-\d{2}-\d{2}): /.exec(String(local('evtprm2') || ''));
if (m && m[1] === today) { setGlobal('DigestDate', today); }
